use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\ThemeVersionChannelVO;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionChannelOptions;

trait ThemeVersionChannelAttributeHolder
{
    protected ThemeVersionChannelVO|ThemeVersionChannelOptions|null $channel = null;
    protected bool $channelAssigned = false;

    public function getChannelOrCurrent(ThemeVersionChannelVO $channel): ThemeVersionChannelVO
    {
        if ($this->channelAssigned) {
            \assert(null !== $this->channel);
            return ThemeVersionChannelVO::from($this->channel);
        } else {
            return $channel;
        }
    }
    public function channelTryBuildInitial(ConstraintFailList $error): ?ThemeVersionChannelVO
    {
        return  ThemeVersionChannelVO::tryFrom($this->channelAssigned ? $this->channel : null, $error);
    }
    public function channel(ThemeVersionChannelVO|ThemeVersionChannelOptions $channel): static
    {
        $this->channel = $channel;
        $this->channelAssigned = true;
        return $this;
    }
    public function getChannel(): ?ThemeVersionChannelOptions
    {
        return $this->channel instanceof ThemeVersionChannelVO ? $this->channel->value() : $this->channel;
    }
    public function isChannelAssigned(): bool
    {
        return $this->channelAssigned;
    }
    public function writeChannelTo(mixed $att): void
    {
        if ($this->channelAssigned) {
            \assert(null !== $this->channel);
            $att->channel($this->channel);
        }
    }
    public function readChannelFrom(mixed $att): void
    {
        if ($att->isChannelAssigned()) {
            $channel = $att->getChannel();
            \assert(null !== $channel);
            $this->channel($channel);
        }
    }
    public function unsetChannel(): static
    {
        $this->channelAssigned = false;
        return $this;
    }
    protected function withDefaultChannel(): void
    {
    }
    protected function withAssertedChannelRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->channelAssigned = $this->channelAssigned) {
            $value->channel = ThemeVersionChannelVO::tryFrom($this->channel, $errorsList);
        }
    }
}
